window.ML_WEEKS = window.ML_WEEKS || {};
window.ML_WEEKS[1] = {"week":1,"title":"从数据到一次可解释的学习","stage":"基础与传统学习","estimated_hours":"10–12小时，可拆成多次学习","prerequisites":["会使用变量、循环和函数即可；Python/C++选一种主线","不要求先学完整本高等数学"],"goals":["把数据、预测、损失、求导、更新与评估连起来","手算两个样本的两次更新","补完三个核心函数，并解释一次新条件下的结果"],"legacy_doc":"06_第一周学习与自测.md","sections":[],"code":{"python_file":"examples/week01.py","cpp_file":"examples/week01.cpp","steps":[{"title":"一条样本怎样进入程序","explanation":"Python的每个元组保存一对(x,y)，C++用pair保存同样的两个数。x是输入，y是目标。这里的数字只是教学样本，不是现实数据。predict输入一个x及当前w、b，返回一个预测数值。","python_lines":[1,5],"cpp_lines":[1,9],"checkpoint":"predict(2,2,1)应该返回5；参数和数据有什么不同？"},{"title":"从一行残差到平均损失","explanation":"遍历样本后，先用预测减标签，再平方并累加。除以样本数只在循环完成后进行。total是浮点数；C++的浮点数除以整数size()仍会进行浮点除法。本例没有额外的1/2系数。","python_lines":[7,12],"cpp_lines":[10,17],"checkpoint":"w=b=0时，两个平方残差是9和25，平均是17。"},{"title":"公式里的求和变成两个累加器","explanation":"同一个残差分别贡献error*x和error。w的偏导多乘x，因为预测wx+b对w求导得到x；对b求导得到1。最后统一乘2/n。返回值的先后顺序固定为w梯度、b梯度。","python_lines":[14,20],"cpp_lines":[18,26],"checkpoint":"原点的dw=-13，db=-8。请解释负号代表的局部变化方向。"},{"title":"先观察，再同步更新","explanation":"第0行输出初始状态。先在旧参数上求出两个梯度，然后更新w、b。C++虽然分成两条赋值，但g已经在旧参数处算完，所以仍是同步梯度下降。输出第2行后停止，恰好完成两次更新。","python_lines":[22,28],"cpp_lines":[27,39],"checkpoint":"第二次更新后w=1.71、b=1.05，MSE=0.16925。把alpha改成1时会怎样？"}],"expected_output":"step=0 w=0.000000 b=0.000000 mse=17.000000\nstep=1 w=1.300000 b=0.800000 mse=1.685000\nstep=2 w=1.710000 b=1.050000 mse=0.169250","python_source":"\"\"\"Two samples: predict, measure, differentiate, and update. No third-party library.\"\"\"\nsamples = [(1.0, 3.0), (2.0, 5.0)]\n\ndef predict(x, w, b):\n    return w * x + b\n\ndef mse(data, w, b):\n    total = 0.0\n    for x, y in data:\n        error = predict(x, w, b) - y\n        total += error * error\n    return total / len(data)\n\ndef gradients(data, w, b):\n    dw, db = 0.0, 0.0\n    for x, y in data:\n        error = predict(x, w, b) - y\n        dw += error * x\n        db += error\n    return 2.0 * dw / len(data), 2.0 * db / len(data)\n\nw, b, alpha = 0.0, 0.0, 0.1\nfor step in range(3):\n    print(f\"step={step} w={w:.6f} b={b:.6f} mse={mse(samples,w,b):.6f}\")\n    if step == 2:\n        break\n    dw, db = gradients(samples, w, b)\n    w, b = w - alpha * dw, b - alpha * db\n","python_html_lines":["<span class=\"sd\">&quot;&quot;&quot;Two samples: predict, measure, differentiate, and update. No third-party library.&quot;&quot;&quot;</span>","<span class=\"n\">samples</span> <span class=\"o\">=</span> <span class=\"p\">[(</span><span class=\"mf\">1.0</span><span class=\"p\">,</span> <span class=\"mf\">3.0</span><span class=\"p\">),</span> <span class=\"p\">(</span><span class=\"mf\">2.0</span><span class=\"p\">,</span> <span class=\"mf\">5.0</span><span class=\"p\">)]</span>","","<span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">predict</span><span class=\"p\">(</span><span class=\"n\">x</span><span class=\"p\">,</span> <span class=\"n\">w</span><span class=\"p\">,</span> <span class=\"n\">b</span><span class=\"p\">):</span>","    <span class=\"k\">return</span> <span class=\"n\">w</span> <span class=\"o\">*</span> <span class=\"n\">x</span> <span class=\"o\">+</span> <span class=\"n\">b</span>","","<span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">mse</span><span class=\"p\">(</span><span class=\"n\">data</span><span class=\"p\">,</span> <span class=\"n\">w</span><span class=\"p\">,</span> <span class=\"n\">b</span><span class=\"p\">):</span>","    <span class=\"n\">total</span> <span class=\"o\">=</span> <span class=\"mf\">0.0</span>","    <span class=\"k\">for</span> <span class=\"n\">x</span><span class=\"p\">,</span> <span class=\"n\">y</span> <span class=\"ow\">in</span> <span class=\"n\">data</span><span class=\"p\">:</span>","        <span class=\"n\">error</span> <span class=\"o\">=</span> <span class=\"n\">predict</span><span class=\"p\">(</span><span class=\"n\">x</span><span class=\"p\">,</span> <span class=\"n\">w</span><span class=\"p\">,</span> <span class=\"n\">b</span><span class=\"p\">)</span> <span class=\"o\">-</span> <span class=\"n\">y</span>","        <span class=\"n\">total</span> <span class=\"o\">+=</span> <span class=\"n\">error</span> <span class=\"o\">*</span> <span class=\"n\">error</span>","    <span class=\"k\">return</span> <span class=\"n\">total</span> <span class=\"o\">/</span> <span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">data</span><span class=\"p\">)</span>","","<span class=\"k\">def</span><span class=\"w\"> </span><span class=\"nf\">gradients</span><span class=\"p\">(</span><span class=\"n\">data</span><span class=\"p\">,</span> <span class=\"n\">w</span><span class=\"p\">,</span> <span class=\"n\">b</span><span class=\"p\">):</span>","    <span class=\"n\">dw</span><span class=\"p\">,</span> <span class=\"n\">db</span> <span class=\"o\">=</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span>","    <span class=\"k\">for</span> <span class=\"n\">x</span><span class=\"p\">,</span> <span class=\"n\">y</span> <span class=\"ow\">in</span> <span class=\"n\">data</span><span class=\"p\">:</span>","        <span class=\"n\">error</span> <span class=\"o\">=</span> <span class=\"n\">predict</span><span class=\"p\">(</span><span class=\"n\">x</span><span class=\"p\">,</span> <span class=\"n\">w</span><span class=\"p\">,</span> <span class=\"n\">b</span><span class=\"p\">)</span> <span class=\"o\">-</span> <span class=\"n\">y</span>","        <span class=\"n\">dw</span> <span class=\"o\">+=</span> <span class=\"n\">error</span> <span class=\"o\">*</span> <span class=\"n\">x</span>","        <span class=\"n\">db</span> <span class=\"o\">+=</span> <span class=\"n\">error</span>","    <span class=\"k\">return</span> <span class=\"mf\">2.0</span> <span class=\"o\">*</span> <span class=\"n\">dw</span> <span class=\"o\">/</span> <span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">data</span><span class=\"p\">),</span> <span class=\"mf\">2.0</span> <span class=\"o\">*</span> <span class=\"n\">db</span> <span class=\"o\">/</span> <span class=\"nb\">len</span><span class=\"p\">(</span><span class=\"n\">data</span><span class=\"p\">)</span>","","<span class=\"n\">w</span><span class=\"p\">,</span> <span class=\"n\">b</span><span class=\"p\">,</span> <span class=\"n\">alpha</span> <span class=\"o\">=</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.0</span><span class=\"p\">,</span> <span class=\"mf\">0.1</span>","<span class=\"k\">for</span> <span class=\"n\">step</span> <span class=\"ow\">in</span> <span class=\"nb\">range</span><span class=\"p\">(</span><span class=\"mi\">3</span><span class=\"p\">):</span>","    <span class=\"nb\">print</span><span class=\"p\">(</span><span class=\"sa\">f</span><span class=\"s2\">&quot;step=</span><span class=\"si\">{</span><span class=\"n\">step</span><span class=\"si\">}</span><span class=\"s2\"> w=</span><span class=\"si\">{</span><span class=\"n\">w</span><span class=\"si\">:</span><span class=\"s2\">.6f</span><span class=\"si\">}</span><span class=\"s2\"> b=</span><span class=\"si\">{</span><span class=\"n\">b</span><span class=\"si\">:</span><span class=\"s2\">.6f</span><span class=\"si\">}</span><span class=\"s2\"> mse=</span><span class=\"si\">{</span><span class=\"n\">mse</span><span class=\"p\">(</span><span class=\"n\">samples</span><span class=\"p\">,</span><span class=\"n\">w</span><span class=\"p\">,</span><span class=\"n\">b</span><span class=\"p\">)</span><span class=\"si\">:</span><span class=\"s2\">.6f</span><span class=\"si\">}</span><span class=\"s2\">&quot;</span><span class=\"p\">)</span>","    <span class=\"k\">if</span> <span class=\"n\">step</span> <span class=\"o\">==</span> <span class=\"mi\">2</span><span class=\"p\">:</span>","        <span class=\"k\">break</span>","    <span class=\"n\">dw</span><span class=\"p\">,</span> <span class=\"n\">db</span> <span class=\"o\">=</span> <span class=\"n\">gradients</span><span class=\"p\">(</span><span class=\"n\">samples</span><span class=\"p\">,</span> <span class=\"n\">w</span><span class=\"p\">,</span> <span class=\"n\">b</span><span class=\"p\">)</span>","    <span class=\"n\">w</span><span class=\"p\">,</span> <span class=\"n\">b</span> <span class=\"o\">=</span> <span class=\"n\">w</span> <span class=\"o\">-</span> <span class=\"n\">alpha</span> <span class=\"o\">*</span> <span class=\"n\">dw</span><span class=\"p\">,</span> <span class=\"n\">b</span> <span class=\"o\">-</span> <span class=\"n\">alpha</span> <span class=\"o\">*</span> <span class=\"n\">db</span>"],"cpp_source":"#include <iomanip>\n#include <iostream>\n#include <utility>\n#include <vector>\nusing Data = std::vector<std::pair<double, double>>;\n\ndouble predict(double x, double w, double b) {\n    return w * x + b;\n}\ndouble mse(const Data& data, double w, double b) {\n    double total = 0.0;\n    for (const auto& p : data) {\n        double error = predict(p.first, w, b) - p.second;\n        total += error * error;\n    }\n    return total / data.size();\n}\nstd::pair<double, double> gradients(const Data& data, double w, double b) {\n    double dw = 0.0, db = 0.0;\n    for (const auto& p : data) {\n        double error = predict(p.first, w, b) - p.second;\n        dw += error * p.first;\n        db += error;\n    }\n    return {2.0 * dw / data.size(), 2.0 * db / data.size()};\n}\nint main() {\n    const Data data{{1.0, 3.0}, {2.0, 5.0}};\n    double w = 0.0, b = 0.0, alpha = 0.1;\n    std::cout << std::fixed << std::setprecision(6);\n    for (int step = 0; step < 3; ++step) {\n        std::cout << \"step=\" << step << \" w=\" << w << \" b=\" << b\n                  << \" mse=\" << mse(data, w, b) << '\\n';\n        if (step == 2) break;\n        auto g = gradients(data, w, b);\n        w -= alpha * g.first;\n        b -= alpha * g.second;\n    }\n}\n","cpp_html_lines":["<span class=\"cp\">#include</span><span class=\"w\"> </span><span class=\"cpf\">&lt;iomanip&gt;</span>","<span class=\"cp\">#include</span><span class=\"w\"> </span><span class=\"cpf\">&lt;iostream&gt;</span>","<span class=\"cp\">#include</span><span class=\"w\"> </span><span class=\"cpf\">&lt;utility&gt;</span>","<span class=\"cp\">#include</span><span class=\"w\"> </span><span class=\"cpf\">&lt;vector&gt;</span>","<span class=\"k\">using</span><span class=\"w\"> </span><span class=\"n\">Data</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"n\">std</span><span class=\"o\">::</span><span class=\"n\">vector</span><span class=\"o\">&lt;</span><span class=\"n\">std</span><span class=\"o\">::</span><span class=\"n\">pair</span><span class=\"o\">&lt;</span><span class=\"kt\">double</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"kt\">double</span><span class=\"o\">&gt;&gt;</span><span class=\"p\">;</span>","","<span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"nf\">predict</span><span class=\"p\">(</span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">x</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">w</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">b</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"p\">{</span>","<span class=\"w\">    </span><span class=\"k\">return</span><span class=\"w\"> </span><span class=\"n\">w</span><span class=\"w\"> </span><span class=\"o\">*</span><span class=\"w\"> </span><span class=\"n\">x</span><span class=\"w\"> </span><span class=\"o\">+</span><span class=\"w\"> </span><span class=\"n\">b</span><span class=\"p\">;</span>","<span class=\"p\">}</span>","<span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"nf\">mse</span><span class=\"p\">(</span><span class=\"k\">const</span><span class=\"w\"> </span><span class=\"n\">Data</span><span class=\"o\">&amp;</span><span class=\"w\"> </span><span class=\"n\">data</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">w</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">b</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"p\">{</span>","<span class=\"w\">    </span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">total</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"mf\">0.0</span><span class=\"p\">;</span>","<span class=\"w\">    </span><span class=\"k\">for</span><span class=\"w\"> </span><span class=\"p\">(</span><span class=\"k\">const</span><span class=\"w\"> </span><span class=\"k\">auto</span><span class=\"o\">&amp;</span><span class=\"w\"> </span><span class=\"n\">p</span><span class=\"w\"> </span><span class=\"o\">:</span><span class=\"w\"> </span><span class=\"n\">data</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"p\">{</span>","<span class=\"w\">        </span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">error</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"n\">predict</span><span class=\"p\">(</span><span class=\"n\">p</span><span class=\"p\">.</span><span class=\"n\">first</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"n\">w</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"n\">b</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"o\">-</span><span class=\"w\"> </span><span class=\"n\">p</span><span class=\"p\">.</span><span class=\"n\">second</span><span class=\"p\">;</span>","<span class=\"w\">        </span><span class=\"n\">total</span><span class=\"w\"> </span><span class=\"o\">+=</span><span class=\"w\"> </span><span class=\"n\">error</span><span class=\"w\"> </span><span class=\"o\">*</span><span class=\"w\"> </span><span class=\"n\">error</span><span class=\"p\">;</span>","<span class=\"w\">    </span><span class=\"p\">}</span>","<span class=\"w\">    </span><span class=\"k\">return</span><span class=\"w\"> </span><span class=\"n\">total</span><span class=\"w\"> </span><span class=\"o\">/</span><span class=\"w\"> </span><span class=\"n\">data</span><span class=\"p\">.</span><span class=\"n\">size</span><span class=\"p\">();</span>","<span class=\"p\">}</span>","<span class=\"n\">std</span><span class=\"o\">::</span><span class=\"n\">pair</span><span class=\"o\">&lt;</span><span class=\"kt\">double</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"kt\">double</span><span class=\"o\">&gt;</span><span class=\"w\"> </span><span class=\"n\">gradients</span><span class=\"p\">(</span><span class=\"k\">const</span><span class=\"w\"> </span><span class=\"n\">Data</span><span class=\"o\">&amp;</span><span class=\"w\"> </span><span class=\"n\">data</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">w</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">b</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"p\">{</span>","<span class=\"w\">    </span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">dw</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"mf\">0.0</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"n\">db</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"mf\">0.0</span><span class=\"p\">;</span>","<span class=\"w\">    </span><span class=\"k\">for</span><span class=\"w\"> </span><span class=\"p\">(</span><span class=\"k\">const</span><span class=\"w\"> </span><span class=\"k\">auto</span><span class=\"o\">&amp;</span><span class=\"w\"> </span><span class=\"n\">p</span><span class=\"w\"> </span><span class=\"o\">:</span><span class=\"w\"> </span><span class=\"n\">data</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"p\">{</span>","<span class=\"w\">        </span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">error</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"n\">predict</span><span class=\"p\">(</span><span class=\"n\">p</span><span class=\"p\">.</span><span class=\"n\">first</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"n\">w</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"n\">b</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"o\">-</span><span class=\"w\"> </span><span class=\"n\">p</span><span class=\"p\">.</span><span class=\"n\">second</span><span class=\"p\">;</span>","<span class=\"w\">        </span><span class=\"n\">dw</span><span class=\"w\"> </span><span class=\"o\">+=</span><span class=\"w\"> </span><span class=\"n\">error</span><span class=\"w\"> </span><span class=\"o\">*</span><span class=\"w\"> </span><span class=\"n\">p</span><span class=\"p\">.</span><span class=\"n\">first</span><span class=\"p\">;</span>","<span class=\"w\">        </span><span class=\"n\">db</span><span class=\"w\"> </span><span class=\"o\">+=</span><span class=\"w\"> </span><span class=\"n\">error</span><span class=\"p\">;</span>","<span class=\"w\">    </span><span class=\"p\">}</span>","<span class=\"w\">    </span><span class=\"k\">return</span><span class=\"w\"> </span><span class=\"p\">{</span><span class=\"mf\">2.0</span><span class=\"w\"> </span><span class=\"o\">*</span><span class=\"w\"> </span><span class=\"n\">dw</span><span class=\"w\"> </span><span class=\"o\">/</span><span class=\"w\"> </span><span class=\"n\">data</span><span class=\"p\">.</span><span class=\"n\">size</span><span class=\"p\">(),</span><span class=\"w\"> </span><span class=\"mf\">2.0</span><span class=\"w\"> </span><span class=\"o\">*</span><span class=\"w\"> </span><span class=\"n\">db</span><span class=\"w\"> </span><span class=\"o\">/</span><span class=\"w\"> </span><span class=\"n\">data</span><span class=\"p\">.</span><span class=\"n\">size</span><span class=\"p\">()};</span>","<span class=\"p\">}</span>","<span class=\"kt\">int</span><span class=\"w\"> </span><span class=\"n\">main</span><span class=\"p\">()</span><span class=\"w\"> </span><span class=\"p\">{</span>","<span class=\"w\">    </span><span class=\"k\">const</span><span class=\"w\"> </span><span class=\"n\">Data</span><span class=\"w\"> </span><span class=\"n\">data</span><span class=\"p\">{{</span><span class=\"mf\">1.0</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"mf\">3.0</span><span class=\"p\">},</span><span class=\"w\"> </span><span class=\"p\">{</span><span class=\"mf\">2.0</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"mf\">5.0</span><span class=\"p\">}};</span>","<span class=\"w\">    </span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">w</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"mf\">0.0</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"n\">b</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"mf\">0.0</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"n\">alpha</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"mf\">0.1</span><span class=\"p\">;</span>","<span class=\"w\">    </span><span class=\"n\">std</span><span class=\"o\">::</span><span class=\"n\">cout</span><span class=\"w\"> </span><span class=\"o\">&lt;&lt;</span><span class=\"w\"> </span><span class=\"n\">std</span><span class=\"o\">::</span><span class=\"n\">fixed</span><span class=\"w\"> </span><span class=\"o\">&lt;&lt;</span><span class=\"w\"> </span><span class=\"n\">std</span><span class=\"o\">::</span><span class=\"n\">setprecision</span><span class=\"p\">(</span><span class=\"mi\">6</span><span class=\"p\">);</span>","<span class=\"w\">    </span><span class=\"k\">for</span><span class=\"w\"> </span><span class=\"p\">(</span><span class=\"kt\">int</span><span class=\"w\"> </span><span class=\"n\">step</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"mi\">0</span><span class=\"p\">;</span><span class=\"w\"> </span><span class=\"n\">step</span><span class=\"w\"> </span><span class=\"o\">&lt;</span><span class=\"w\"> </span><span class=\"mi\">3</span><span class=\"p\">;</span><span class=\"w\"> </span><span class=\"o\">++</span><span class=\"n\">step</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"p\">{</span>","<span class=\"w\">        </span><span class=\"n\">std</span><span class=\"o\">::</span><span class=\"n\">cout</span><span class=\"w\"> </span><span class=\"o\">&lt;&lt;</span><span class=\"w\"> </span><span class=\"s\">&quot;step=&quot;</span><span class=\"w\"> </span><span class=\"o\">&lt;&lt;</span><span class=\"w\"> </span><span class=\"n\">step</span><span class=\"w\"> </span><span class=\"o\">&lt;&lt;</span><span class=\"w\"> </span><span class=\"s\">&quot; w=&quot;</span><span class=\"w\"> </span><span class=\"o\">&lt;&lt;</span><span class=\"w\"> </span><span class=\"n\">w</span><span class=\"w\"> </span><span class=\"o\">&lt;&lt;</span><span class=\"w\"> </span><span class=\"s\">&quot; b=&quot;</span><span class=\"w\"> </span><span class=\"o\">&lt;&lt;</span><span class=\"w\"> </span><span class=\"n\">b</span>","<span class=\"w\">                  </span><span class=\"o\">&lt;&lt;</span><span class=\"w\"> </span><span class=\"s\">&quot; mse=&quot;</span><span class=\"w\"> </span><span class=\"o\">&lt;&lt;</span><span class=\"w\"> </span><span class=\"n\">mse</span><span class=\"p\">(</span><span class=\"n\">data</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"n\">w</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"n\">b</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"o\">&lt;&lt;</span><span class=\"w\"> </span><span class=\"sc\">&#39;\\n&#39;</span><span class=\"p\">;</span>","<span class=\"w\">        </span><span class=\"k\">if</span><span class=\"w\"> </span><span class=\"p\">(</span><span class=\"n\">step</span><span class=\"w\"> </span><span class=\"o\">==</span><span class=\"w\"> </span><span class=\"mi\">2</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"k\">break</span><span class=\"p\">;</span>","<span class=\"w\">        </span><span class=\"k\">auto</span><span class=\"w\"> </span><span class=\"n\">g</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"n\">gradients</span><span class=\"p\">(</span><span class=\"n\">data</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"n\">w</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"n\">b</span><span class=\"p\">);</span>","<span class=\"w\">        </span><span class=\"n\">w</span><span class=\"w\"> </span><span class=\"o\">-=</span><span class=\"w\"> </span><span class=\"n\">alpha</span><span class=\"w\"> </span><span class=\"o\">*</span><span class=\"w\"> </span><span class=\"n\">g</span><span class=\"p\">.</span><span class=\"n\">first</span><span class=\"p\">;</span>","<span class=\"w\">        </span><span class=\"n\">b</span><span class=\"w\"> </span><span class=\"o\">-=</span><span class=\"w\"> </span><span class=\"n\">alpha</span><span class=\"w\"> </span><span class=\"o\">*</span><span class=\"w\"> </span><span class=\"n\">g</span><span class=\"p\">.</span><span class=\"n\">second</span><span class=\"p\">;</span>","<span class=\"w\">    </span><span class=\"p\">}</span>","<span class=\"p\">}</span>"]},"exercises":[{"prompt":"基础：用普通循环实现mse，并手算w=1、b=0时的输出。","hints":["先分别算两个预测，再算残差。","残差为−2与−3；平方后最后取平均。"],"answer":"预测为1、2，残差为−2、−3，MSE=(4+9)/2=6.5。循环体累加error*error，循环结束返回total/len(data)。如果得到13，说明漏掉平均；若得到−2.5，说明没有平方。","prompt_html":"<p>基础：用普通循环实现mse，并手算w=1、b=0时的输出。</p>\n","answer_html":"<p>预测为1、2，残差为−2、−3，MSE=(4+9)/2=6.5。循环体累加error*error，循环结束返回total/len(data)。如果得到13，说明漏掉平均；若得到−2.5，说明没有平方。</p>\n","hints_html":["<p>先分别算两个预测，再算残差。</p>\n","<p>残差为−2与−3；平方后最后取平均。</p>\n"]},{"prompt":"改动：仍从w=1、b=0开始，用0.1做一次同步更新。写出参数与新损失。","hints":["先计算dw=−8、db=−5。","新w=1−0.1×(−8)，新b=0−0.1×(−5)。"],"answer":"w=1.8，b=0.5，预测2.3与4.1，残差−0.7与−0.9，MSE=(0.49+0.81)/2=0.65。两个梯度必须来自同一组旧参数。","prompt_html":"<p>改动：仍从w=1、b=0开始，用0.1做一次同步更新。写出参数与新损失。</p>\n","answer_html":"<p>w=1.8，b=0.5，预测2.3与4.1，残差−0.7与−0.9，MSE=(0.49+0.81)/2=0.65。两个梯度必须来自同一组旧参数。</p>\n","hints_html":["<p>先计算dw=−8、db=−5。</p>\n","<p>新w=1−0.1×(−8)，新b=0−0.1×(−5)。</p>\n"]},{"prompt":"迁移：把数据换成(0,1)、(1,3)、(2,5)，从原点手算梯度，再用程序核对。","hints":["n现在是3。","dw=2/3×[−1×0−3×1−5×2]。"],"answer":"原损失(1+9+25)/3=35/3；dw=−26/3，db=−6。学习率0.1更新后w=13/15≈0.866667，b=0.6。不能继续把2/n当成1；样本数发生了改变。","prompt_html":"<p>迁移：把数据换成(0,1)、(1,3)、(2,5)，从原点手算梯度，再用程序核对。</p>\n","answer_html":"<p>原损失(1+9+25)/3=35/3；dw=−26/3，db=−6。学习率0.1更新后w=13/15≈0.866667，b=0.6。不能继续把2/n当成1；样本数发生了改变。</p>\n","hints_html":["<p>n现在是3。</p>\n","<p>dw=2/3×[−1×0−3×1−5×2]。</p>\n"]}],"quiz":[{"question":"这里的梯度是对谁求导？","options":["样本编号","随机种子","训练次数","模型参数w与b"],"answer":3,"explanation":"损失关于参数的变化率用于更新参数。数学上也可对输入求导，但用途不同。","explanation_html":"<p>损失关于参数的变化率用于更新参数。数学上也可对输入求导，但用途不同。</p>\n"},{"question":"所有样本完整复制一遍，普通MSE的全量梯度会怎样？","options":["减半","必定变成零","翻倍","不变"],"answer":3,"explanation":"求和与样本数同时翻倍，平均及梯度不变；损失之和则不同。","explanation_html":"<p>求和与样本数同时翻倍，平均及梯度不变；损失之和则不同。</p>\n"},{"question":"正确的梯度配上很大的学习率，可能发生什么？","options":["测试集变大","必定更快收敛","梯度自动变小","损失上升"],"answer":3,"explanation":"梯度描述局部方向，大步跨出局部有效范围后损失可能增大。","explanation_html":"<p>梯度描述局部方向，大步跨出局部有效范围后损失可能增大。</p>\n"},{"question":"用测试分数挑选学习率之后，该测试集是什么状态？","options":["仍是首次独立评估","只要固定种子就不受影响","样本多就不会泄漏","已参与方案选择"],"answer":3,"explanation":"选择依赖了测试反馈，最终评价需要新的独立数据，或明确声明选择影响。","explanation_html":"<p>选择依赖了测试反馈，最终评价需要新的独立数据，或明确声明选择影响。</p>\n"}],"review_questions":[{"question":"不用背术语，解释一轮机器学习发生了什么。","answer":"输入数据经当前模型得到预测；损失衡量预测与标签的差异；梯度给出参数的局部影响；沿负梯度做小步更新。随后用未参与拟合的数据评价效果。训练损失下降只是其中一个观察。","answer_html":"<p>输入数据经当前模型得到预测；损失衡量预测与标签的差异；梯度给出参数的局部影响；沿负梯度做小步更新。随后用未参与拟合的数据评价效果。训练损失下降只是其中一个观察。</p>\n"},{"question":"手写梯度、差分、SymPy与PyTorch分别帮了什么忙？","answer":"手写梯度把自己推导的公式算成数值；差分用函数两侧值近似导数；SymPy生成符号导数表达式；PyTorch按记录的运算依赖执行链式法则。四者一致还需检查共同使用的损失定义是否正确。","answer_html":"<p>手写梯度把自己推导的公式算成数值；差分用函数两侧值近似导数；SymPy生成符号导数表达式；PyTorch按记录的运算依赖执行链式法则。四者一致还需检查共同使用的损失定义是否正确。</p>\n"}],"deliverables":["两个初值下的一次手算与对应输出","一种语言的预测、MSE、梯度三个函数","8–10分钟独立讲解与一次变式答案"],"acceptance":["能把每个参数和返回值对应到公式","能说明学习率过大与梯度写错的区别","能解释训练、验证和测试各自的角色"],"references":[{"title":"Python官方：控制流与函数","url":"https://docs.python.org/3.12/tutorial/controlflow.html","note":"不熟悉for、def、lambda时按需查阅。"},{"title":"NumPy官方：gradient","url":"https://numpy.org/doc/stable/reference/generated/numpy.gradient.html","note":"区分采样差分与参数自动微分；本周主程序不依赖它。"}],"search_text":"从数据到一次可解释的学习 把数据、预测、损失、求导、更新与评估连起来 手算两个样本的两次更新 补完三个核心函数，并解释一次新条件下的结果 # 第一周 从数据到一次可解释的学习\n\n这一周的目标是把六个环节连起来：**数据是什么，模型如何预测，损失如何衡量错误，导数如何指示变化，程序如何更新参数，怎样检验新样本上的效果**。学完后，你应能用自己的例子解释这条链，并在一种语言中独立补完关键计算。\n\n建议阅读[公式排版版](阅读版/第一周学习.html)。本文件保留可编辑的数学公式；排版版不依赖网络或阅读器的公式插件。代码语法与数学符号分开呈现，求和、分式与偏导不再混放在代码框里。\n\n本周采用“读懂完整示例 → 改一个条件 → 补三个函数 → 独立改写”的顺序。python作为默认主线，c++提供等价版本；选一种作为独立实现语言即可，不要求一周同时熟练两套工具。原先的[第二版笔记](06_第二版.md)保持原样，关于二分之一系数和一阶泰勒近似的想法已在下文展开。\n\n## 学习安排与内容对照\n\n| 课次与时间 | 完整讲解内容 | 立即练习 | 需要留下的结果 |\n|---|---|---|---|\n| 第1课 1.5小时 | 样本、特征、标签；回归与分类；标量、向量、矩阵与形状 | 给一个预测任务设计数据表，指出不能提前知道的信息 | 一张数据表与形状说明 |\n| 第2课 1.5小时 | 模型、参数、超参数；误差、mse、均值基线 | 比较三条预测规则，手算每个样本的误差 | 一张逐样本计算表 |\n| 第3课 1.5小时 | 导数、偏导、梯度；求导规则、链式法则、中心差分 | 手推两个偏导，用差分核对一个数 | 一份推导与数值核对 |\n| 第4课 2小时 | 负梯度与学习率；两次完整更新；公式怎样变成循环 | 运行参考程序，逐行解释，再改初始参数 | 参数轨迹与修改前的预测 |\n| 第5课 2小时 | python/c++函数与容器；填空、调试、求导库的分工 | 选择一种语言补完三个核心函数 | 可运行的练习版与自查结果 |\n| 第6课 1.5小时 | 训练、验证、测试；泛化与泄漏；迁移自测 | 读懂80样本参考实验，讲解结果并答题 | 简短实验记录与8–10分钟讲解 |\n\n合计10小时，另留0–2小时补学。80样本实验本周要求**读懂并运行参考实现**；数据生成、文件读写与整套实验的独立重写放到第2周。第二语言、numpy、sympy与pytorch示例按需对照，不全算作本周必做作业。\n\n## 第1课 把一个问题写成数据\n\n### 样本 特征 标签\n\n假设要根据房间面积预测租金。一行历史记录是一份样本；预测时能获得的面积是特征；希望预测的租金是标签。真实任务还可能需要地区、房龄等特征，这里只用面积说明数据结构，并不假定面积足以解释所有差异。\n\n| 样本编号 | 面积这个特征 x | 租金这个标签 y |\n|---|---|---|\n| 1 | 1 | 3 |\n| 2 | 2 | 5 |\n\n本周计算使用上面两个抽象数值点，不把它们当作真实租房数据。预测连续数值叫**回归**；预测“垃圾邮件/正常邮件”这样的离散类别叫**分类**。两者都可以从带标签样本学习，属于监督学习。\n\n特征必须在实际做预测的时刻能够取得。若预测明天销量，却把明天最终成交金额作为输入，就可能提前泄露答案。能从文件中读到，不等于预测时能够使用。\n\n**停下来想：**预测学生下一次测验成绩，哪些可以作特征：过去成绩、本次测验结束后才统计的答对题数、此前练习时间？说明理由，不只回答“能”或“不能”。\n\n### 标量 向量 矩阵与形状\n\n标量是一个数，例如一个样本的面积。向量是一组按约定排列的数，例如同一样本的面积与房龄。矩阵可以用来组织多个样本：通常一行一个样本，一列一个特征。\n\n| 对象 | 本周单特征写法 | 一般形状 | 含义 |\n|---|---|---|---|\n| 单个特征值 | 1.0 | 标量 | 一个样本的一项信息 |\n| 一批单特征数据 | `[1.0, 2.0]` | `(n,)` | n个样本的一项特征 |\n| 特征矩阵 x | `[[1.0], [2.0]]` | `(n,d)` | n个样本、d个特征 |\n| 权重向量 w | `[0.0]` | `(d,)` | 每个特征一个权重 |\n| 标签 y与预测值 | `[3.0, 5.0]` | `(n,)` | 每个样本一个值 |\n| 偏置 b与损失 l | 0.0与17.0 | 标量 | 一个全局偏置与一个汇总误差 |\n\n多特征预测可以写成：\n\n$$\n\\hat{\\mathbf{y}}=x\\mathbf{w}+b\n$$\n\n意思是每一行特征与权重作点积，再加上同一个偏置。若x是3行2列，权重有2个数，预测就应有3个数。不要只问代码是否能执行，还要问输出是否确实“一行样本对应一个预测”。numpy中的 `(n,)` 与 `(n,1)` 不是同一种形状；混用时可能发生广播，意外产生 `(n,n)` 误差矩阵，详见[编程辅助](07_python与c++编程辅助.md)。\n\n**本课练习：**自己造一个“3个样本、2个特征、1个标签”的数据表。标出x与y，给出形状，并说明列的顺序为什么不能在预测时随意交换。\n\n## 第2课 从模型到可以比较的损失\n\n### 模型 参数与超参数\n\n先选择最简单的一种预测规则：\n\n$$\n\\hat y_i=wx_i+b\n$$\n\n其中i是样本编号，帽子表示预测值；w控制斜率，b控制整体上下平移。x是已经给定的输入，y是用于比较的标签，训练调整的是w和b。选择“用一条直线”是建模决定，并不是程序从所有可能规则中自动发现了直线。\n\n| 名称 | 本周例子 | 怎样确定 |\n|---|---|---|\n| 参数 | w、b | 通过训练数据与优化过程调整 |\n| 超参数 | 学习率、更新次数 | 由人设定或使用验证集选择 |\n| 数据 | x、y | 来源于观察或明确规定的生成过程 |\n| 模型形式 | 一条直线 | 由任务和建模假设选择 |\n\n先不训练，手工试三组参数：全零预测、恒定预测4、直线预测2x+1。训练的作用是用有组织的方式寻找参数，代替一直凭感觉猜数字。\n\n### 为什么定义误差与均方误差\n\n本周统一用“预测减真实值”定义残差：\n\n$$\ne_i=\\hat y_i-y_i\n$$\n\n残差为负表示预测偏低，为正表示偏高。若两个残差是2和−2，直接平均得到0，却不能说完全预测正确。均方误差先平方，再取平均：\n\n$$\nl(w,b)=\\frac{1}{n}\\sum_{i=1}^{n}(wx_i+b-y_i)^2\n$$\n\n这里n是样本数，求和符号表示把每个样本的平方残差加起来。本页采用普通mse，**没有额外除以2**。平方避免正负抵消，同时更强调大误差；如果标签单位是元，mse的单位是元的平方，不能把mse直接当成平均相差多少元。\n\n| 预测规则 | 两个预测 | 两个残差 | mse |\n|---|---|---|---|\n| w=0，b=0 | 0，0 | −3，−5 | 17 |\n| w=0，b=4 | 4，4 | 1，−1 | 1 |\n| w=2，b=1 | 3，5 | 0，0 | 0 |\n\n恒定预测训练标签的均值，是一种简单的**基线**。它回答“如果不利用输入特征，能做到什么程度”。在mse下，最佳恒定预测是训练标签均值；这条结论依赖于使用平方损失。\n\n**本课练习：**改成w=1、b=0，独立写出预测、残差与mse。再把一个标签5改成50，观察平方损失如何放大大误差。不要据此宣布mse“不好”，而应讨论任务是否真的要让大错误付出更高代价。\n\n## 第3课 求导到底在求什么\n\n### 从斜率到局部变化率\n\n直线f(t)=3t+2每增加一小段t，输出增加约3倍，导数就是3。曲线的变化速度会随位置改变，例如：\n\n$$\nf(t)=t^2,\\qquad f'(t)=2t\n$$\n\n在t=3处导数是6，表示t增加一个很小的量h时，函数值约增加6h。它不是说“t增加任意大小，输出都准确增加6倍”。例如h=0.1时，实际增加0.61，一阶估计是0.6。\n\n学习参数时，我们关心的是**参数变化会怎样影响损失**。对w求偏导，暂时固定b与所有样本；对b求偏导，暂时固定w与所有样本。把各参数的偏导收集起来，就得到梯度。本例梯度有两个分量，分别对应w与b。\n\n### 本周真正需要的求导规则\n\n| 函数 | 对t求导 | 应怎样理解 |\n|---|---|---|\n| 常数c | 0 | 输入变化不影响输出 |\n| t | 1 | 输入增加多少，输出增加多少 |\n| t的平方 | 2t | 同一曲线在不同位置有不同斜率 |\n| c乘f(t) | c乘f的导数 | 整体缩放也缩放变化率 |\n| f(t)+g(t) | 两个导数相加 | 总变化来自各部分变化 |\n| 外层函数作用于内层函数 | 外层导数乘内层导数 | 一层变化经过另一层传播，称为链式法则 |\n\n对一个样本，把计算分成三步：预测z=wx+b，残差e=z−y，平方误差q=e²。q对e的导数是2e，e对z的导数是1，而z对w的导数是x。因此：\n\n$$\n\\frac{\\partial e_i^2}{\\partial w}=2e_i\\,x_i\n$$\n\n同理，z对b的导数是1，所以：\n\n$$\n\\frac{\\partial e_i^2}{\\partial b}=2e_i\n$$\n\n最后对所有样本求和并除以n，就得到真正需要写进程序的两个式子：\n$$\n\\frac{\\partial l}{\\partial w}=\\frac{2}{n}\\sum_{i=1}^{n}e_i x_i\n$$\n\n$$\n\\frac{\\partial l}{\\partial b}=\\frac{2}{n}\\sum_{i=1}^{n}e_i\n$$\n\n请留意：对w求导时多出来的x不是记忆口诀，它来自预测对w的变化率。若把残差定义改成“真实减预测”，整套推导的符号也必须一起调整，不能只改程序的一行残差。\n\n### 用中心差分核对结果\n\n如果已经有一个能计算损失的函数，就可以轻微改变w，观察两侧损失之差：\n\n$$\n\\frac{\\partial l}{\\partial w}\\approx\\frac{l(w+h,b)-l(w-h,b)}{2h}\n$$\n\n这个方法叫数值差分，返回的是近似导数值，不返回解析公式。h表示探测间距，**不是训练学习率**。本周可先用h=0.00001。h过大可能使局部近似变差，过小又可能使浮点数相减丢失有效数字，不能简单认为越小越准确。\n\n例如f(t)=t³在t=2处，解析导数是12；中心差分的精确表达式为12+h²，h=0.1时得到12.01。本周的线性回归mse对参数是二次函数，精确算术下中心差分恰好能给出导数；实际程序仍有浮点误差。\n\n**本课练习：**固定w=0、b=0，先手算梯度，再用损失函数差分核对w的偏导。然后改为w=1、b=0重做，不能只验证原点。更多求导工具见[编程辅助中的求导方式](07_python与c++编程辅助.md)。\n\n## 第4课 怎样走出一次学习更新\n\n### 为什么沿负梯度更新\n\n在当前位置，正偏导表示参数稍微增加会使损失增大，所以可以尝试减小参数；负偏导则相反。更新规则是：\n\n$$\nw_{t+1}=w_t-\\alpha\\frac{\\partial l}{\\partial w}(w_t,b_t)\n$$\n\n$$\nb_{t+1}=b_t-\\alpha\\frac{\\partial l}{\\partial b}(w_t,b_t)\n$$\n\nt是更新轮次，alpha是学习率。两个偏导必须使用**同一组旧参数**计算，然后同时应用更新。不能先更新w，再把新w代入计算b的梯度，却仍把它称为同一次标准梯度下降。\n\n你在第二版笔记中提到的一阶泰勒近似，可以把这个方向解释得更清楚。记g为当前梯度、theta为参数向量；在变化足够小且函数可微的局部范围内：\n\n$$\nl(\\theta-\\alpha g)\\approx l(\\theta)-\\alpha\\|g\\|^2\n$$\n\n其中梯度范数的平方就是各个偏导平方的和。当alpha为正、梯度不为零时，右侧比原损失小。但这是局部近似，步子过大时高阶项不能忽略，实际损失可以上升；对于更一般的模型，梯度为零也不自动表示找到全局最优。\n\n### 两次更新全部算出来\n\n在w=0、b=0处，残差是−3与−5：\n\n$$\ng_w=(-3)\\times1+(-5)\\times2=-13\n$$\n\n$$\ng_b=(-3)+(-5)=-8\n$$\n\n学习率取0.1，第一次更新得到w=1.3、b=0.8。再次计算残差−0.9与−1.6，得到新梯度−4.1与−2.5；第二次更新得到w=1.71、b=1.05。\n\n| 已完成更新次数 | w | b | 对x=1的预测 | 对x=2的预测 | 当前mse |\n|---|---|---|---|---|---|\n| 0 | 0 | 0 | 0 | 0 | 17 |\n| 1 | 1.3 | 0.8 | 2.1 | 3.4 | 1.685 |\n| 2 | 1.71 | 1.05 | 2.76 | 4.47 | 0.16925 |\n\n![两次更新后的直线与训练样本](assets_week01/two_updates.svg)\n\n图中的横轴是输入x，纵轴是输出y。它展示参数如何改变预测线，不是独立测试的证据。两个点可以被无数其他形状的函数经过，仅拟合它们不能证明现实规律就是一条直线。\n\n把学习率改为1，从零出发一次就得到w=13、b=8，损失升到582.5。梯度方向可以没有算错，更新仍会因步长过大而失败。把损失整体除以2会让梯度也减半；在本例普通梯度下降、没有其他变化时，把学习率乘2才能保留相同的参数更新幅度。\n\n### 一段可直接运行的最小python程序\n\n先读懂下面的完整程序。它只依赖python自身，和数学推导一一对应：\n\n```python\nsamples = [(1.0, 3.0), (2.0, 5.0)]\nw, b = 0.0, 0.0\nalpha = 0.1\n\nfor step in range(3):\n    errors = [w * x + b - y for x, y in samples]\n    loss = sum(e * e for e in errors) / len(samples)\n    print(f\"step={step}, w={w:.6f}, b={b:.6f}, loss={loss:.6f}\")\n    if step == 2:\n        break\n    dw = 2.0 * sum(e * x for e, (x, y) in zip(errors, samples)) / len(samples)\n    db = 2.0 * sum(errors) / len(samples)\n    w, b = w - alpha * dw, b - alpha * db\n```\n\n第一行把每个样本保存为一对数。列表推导式逐个计算残差；sum把各项加起来，len提供样本数；zip把残差与对应样本配对。最后一行的右侧先计算完毕，再把结果赋给w和b，所以使用的是同一组旧参数。\n\n预期输出中的loss依次为17.000000、1.685000、0.169250。分函数的完整版本和c++对应实现见[python参考](week01_support/reference_python.py)与[c++参考](week01_support/reference_cpp.cpp)，运行步骤见[代码使用说明](week01_support/readme.md)。\n\n## 第5课 逐步减少编程帮助\n\n### 先选一种语言完成\n\n| 阶段 | 你做什么 | 怎样判断完成 |\n|---|---|---|\n| 跟读 | 运行参考版本，找到预测、损失、梯度和更新位置 | 能指着代码说出每个输入与返回值的数学含义 |\n| 改动 | 初始参数改为w=1、b=0，运行前先预测 | 损失6.5，梯度−8与−5；能说明为何不同 |\n| 填空 | 在starter里补预测、mse与解析梯度 | 两次更新、均值基线与中心差分检查一致 |\n| 迁移 | 换成自己设计的3个样本，独立调用这些函数 | 不依赖旧答案也能核对一轮更新 |\n\n填空文件：[python练习版](week01_support/starter_python.py)、[c++练习版](week01_support/starter_cpp.cpp)。它们含待完成项，未填写前报错是预期行为。卡住时逐层看[提示](week01_support/hints.txt)，不必立刻从空文件独立写完整实验框架。\n\nc++的平方写成 `e * e`，python可写 `e * e` 或 `e ** 2`；两者的 `^` 都不是普通数值平方运算。c++里用 `2.0 / n` 避免整数除法。检查数组长度、样本对应关系和浮点数类型，往往比先调学习率更有效。\n\n### 求导函数和库分别帮你做什么\n\n| 方式 | 本周怎么用 | 得到什么 |\n|---|---|---|\n| 解析求导后手写函数 | 把上面的两个偏导实现为循环 | 某组参数处的准确公式计算值，存在浮点舍入 |\n| 中心差分 | 对损失函数左右取值 | 近似导数数值，用来交叉检查 |\n| sympy符号求导 | 用diff对数学表达式求导 | 新的符号表达式，再代入数值得到结果 |\n| pytorch自动微分 | 保留张量计算过程，再反向传播 | 相对于参数的梯度数值 |\n\nnumpy负责数组运算，它的 `gradient` 是对采样数据作数值差分，并不自动追踪任意模型的计算图；sympy的 `diff` 才是这里的符号求导。c++标准库没有通用符号或自动求导接口，本周用手写梯度与中心差分就能完成。[numpy官方说明](https://numpy.org/doc/stable/reference/generated/numpy.gradient.html)、[sympy求导教程](https://docs.sympy.org/latest/tutorials/intro-tutorial/calculus.html)\n\n[python与c++编程辅助](07_python与c++编程辅助.md)提供函数、容器、numpy形状、sympy与pytorch的短示例以及c++库说明。现在先用这些工具核对一个导数；完整神经网络反向传播仍放在第9至10周。\n\n## 第6课 从训练成功走向有效评估\n\n### 三份数据回答三个不同问题\n\n训练集用于调整w和b；验证集用于选择学习率、更新轮数或其他方案；测试集用于方案固定后的最终评估。只要看过某份数据上的结果并据此改了方案，它就已经在帮助选择，不能继续假装它完全独立。\n\n第一次更新后的训练损失由17下降到1.685，但仍差于恒定预测4的基线损失1。第二次更新的0.16925虽优于基线，也仅说明训练样本上的比较。泛化关心的是未来相关样本；不仅要有独立评估，还要考虑评估数据是否代表将来的使用情形。\n\n训练损失和验证损失都高，可能是还没训练好、模型太简单、数据或实现有问题；训练很低而验证高，可能是过拟合、划分问题或分布变化。它们是排查线索，不是只看一张图就能确定的诊断。先检查实现和数据，再一次改变一个因素。\n\n### 80个样本的带教实验\n\n本周先运行已提供的参考实现，并回答它为何这样设计。数据生成规则是：\n\n$$\ny=2x+1+\\varepsilon,\\qquad\\varepsilon\\sim\\mathcal{n}(0,0.3^2)\n$$\n\nx在−2至2之间均匀采样。epsilon（ε）代表加在直线输出上的随机噪声；波浪号表示“服从某个分布”，n表示正态分布，括号里的0是均值，0.3²是方差，所以标准差是0.3。均值为0表示噪声总体不偏向正或负，不意味着这一批抽到的噪声均值恰好为0。这里先认识它如何让点偏离直线，概率分布的系统推导留到后续。\n\n使用随机种子42生成80个样本，打乱后固定48个训练、16个验证、16个测试。seed固定的是特定实现的随机过程；python与c++使用相同seed不保证产生同一份数据，所以配套程序让c++读取python导出的同一份csv。\n\n三档学习率0.01、0.1、1.0都从零参数开始，在训练集最多更新100次。参考实现记录训练和验证轨迹，非有限数会被标记；只有完成并产生有限结果的候选参加选择。**数值有限也不等于训练有效**，损失巨大但有限的候选仍应如实保留。\n\n使用第100步的验证mse选择方案，选择后只评估这一模型与训练均值基线在测试集上的mse。不要用三个测试分数来选学习率。16个测试样本带来较大不确定性，这次实验用于学评估流程，不能证明某个学习率对所有数据最优。\n\n**本课练习：**在记录中指出“哪一行拟合参数、哪一步选择学习率、哪一步首次看测试结果”。再提出一个需要分组而不能随意按行划分的例子，例如同一用户多条记录。第2周再独立重写完整流程。\n\n## 综合自测 先答后看参考\n\n1. 预测明天销量时，历史销量、天气预报、明天最终成交金额分别能否作特征？需要说明预测时点。\n2. 3个样本、2个特征时，x、权重和预测的形状分别是什么？本周两个样本的损失又是什么形状？\n3. w、b、学习率和训练次数中，哪些是模型参数，哪些是超参数？\n4. 两个残差为2与−2时，平均残差与mse分别是多少？哪一个会隐藏预测错误？\n5. w=1、b=0时，本周两个点的损失、w偏导和b偏导分别是多少？请写中间过程。\n6. 为什么w偏导中有x，而b偏导中没有？用链式法则解释。\n7. 已经算出dw后立刻修改w，再用新w计算db，是否与文中的同步更新相同？\n8. 损失整体除以2但学习率不变，一次梯度下降的参数变化会怎样？\n9. 学习率改为1导致损失变大，是否必然说明梯度公式写错？\n10. 把所有训练样本完整复制一遍，mse与一次全量梯度更新是否改变？如果使用损失之和呢？\n11. sympy diff、numpy gradient与pytorch backward返回或计算的对象有什么区别？本周不使用任何第三方求导库能否训练？\n12. 看完测试误差后决定再换学习率，之后得到的同一测试集分数还可以当作首次独立评估吗？\n\n## 自测参考与过关方式\n\n1. 历史销量通常可用；天气预报需使用预测时已经发布的版本；明天最终成交金额当时未知，不应作为输入。还需检查特征是否隐含标签。\n2. x为(3,2)，权重为(2,)，预测为(3,)；mse把所有样本误差汇总成一个标量。标签与预测应逐样本一一对应。\n3. w、b是参数；学习率、训练次数是超参数。参数可以通过学习确定，但决定怎样训练也需要独立验证。\n4. 平均残差0，mse为4；直接平均残差会因为符号抵消而隐藏错误。\n5. 预测1、2，残差−2、−3，损失(4+9)/2=6.5；w偏导−2×1−3×2=−8，b偏导−2−3=−5。\n6. 预测wx+b对w的导数为x，对b的导数为1；外层平方误差的2e通过链式法则与它们相乘。\n7. 不同。它使用了两个不同位置的梯度分量；应在旧w、b处算好两个偏导再更新。\n8. 梯度与参数变化都减半；对本例普通梯度下降，把学习率乘2才恢复原更新幅度。\n9. 不必然。正确的局部下降方向配上过大步长也会增加损失；本例从零更新得到w=13、b=8，mse=582.5。\n10. 对同一参数的一次全量更新，mse及其梯度不变；损失之和及其梯度翻倍。按样本逐步更新时，执行次数也可能改变，要另行讨论。\n11. sympy生成符号导数表达式，numpy gradient估计采样值的数值导数，pytorch backward通过计算图把梯度累积到相应张量。解析手写梯度足以完成本周训练。\n12. 不可以。该测试结果已参与方案选择。可以把它转为开发证据，最终评价需要新的独立数据或明确声明评估已受选择影响。\n\n用[三条验收线](02_讲解理解实践验收.md)分别评分：讲解、理解、实践各至少6/8且无0分。主讲解用8–10分钟回答“数据到参数更新再到评估怎样连起来”；实践只要求一种语言的三个核心函数与一次变式正确。运行参考程序是起点，独立补完和解释才是过关证据。\n\n## 本周已讲授与后续内容的边界\n\n| 规划目标 | 对应讲解 | 验收证据 |\n|---|---|---|\n| 数据概念与预测任务 | 第1课的数据表与预测时点 | 自测1，自己造一个任务 |\n| 向量与矩阵形状 | 第1课形状表与3×2练习 | 自测2，解释一个广播错误 |\n| 模型与参数 | 第2课三种预测规则 | 自测3，说明参数与超参数 |\n| 损失和基线 | 第2课逐样本计算，第6课比较 | 自测4，完整误差表 |\n| 求导和首次更新 | 第3、4课推导与程序 | 自测5至10，梯度核对 |\n| 编程能力 | 第5课和辅助文档 | 一种语言的填空版与变式 |\n| 训练与泛化 | 第6课的评估流程 | 自测12，解释一次结果的范围 |\n\n第2周进一步学习批量矩阵实现、线性回归的完整优化实验和独立编程；概率分类与交叉熵从第3周开始。2026年10月23日已补充[第2–24周交互课程](阅读版/index.html#week-2)，包括教学正文、分步代码、练习、自测与参考答案。项目中的真实训练与评估仍需自己完成并留下记录。\n","body_html":"<section class=\"lesson-section\" id=\"w1-section-1\"><h2>学习安排与内容对照</h2><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>课次与时间</th>\n<th>完整讲解内容</th>\n<th>立即练习</th>\n<th>需要留下的结果</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>第1课 1.5小时</td>\n<td>样本、特征、标签；回归与分类；标量、向量、矩阵与形状</td>\n<td>给一个预测任务设计数据表，指出不能提前知道的信息</td>\n<td>一张数据表与形状说明</td>\n</tr>\n<tr>\n<td>第2课 1.5小时</td>\n<td>模型、参数、超参数；误差、MSE、均值基线</td>\n<td>比较三条预测规则，手算每个样本的误差</td>\n<td>一张逐样本计算表</td>\n</tr>\n<tr>\n<td>第3课 1.5小时</td>\n<td>导数、偏导、梯度；求导规则、链式法则、中心差分</td>\n<td>手推两个偏导，用差分核对一个数</td>\n<td>一份推导与数值核对</td>\n</tr>\n<tr>\n<td>第4课 2小时</td>\n<td>负梯度与学习率；两次完整更新；公式怎样变成循环</td>\n<td>运行参考程序，逐行解释，再改初始参数</td>\n<td>参数轨迹与修改前的预测</td>\n</tr>\n<tr>\n<td>第5课 2小时</td>\n<td>Python/C++函数与容器；填空、调试、求导库的分工</td>\n<td>选择一种语言补完三个核心函数</td>\n<td>可运行的练习版与自查结果</td>\n</tr>\n<tr>\n<td>第6课 1.5小时</td>\n<td>训练、验证、测试；泛化与泄漏；迁移自测</td>\n<td>读懂80样本参考实验，讲解结果并答题</td>\n<td>简短实验记录与8–10分钟讲解</td>\n</tr>\n</tbody>\n</table></div>\n<p>合计10小时，另留0–2小时补学。80样本实验本周要求<strong>读懂并运行参考实现</strong>；数据生成、文件读写与整套实验的独立重写放到第2周。第二语言、NumPy、SymPy与PyTorch示例按需对照，不全算作本周必做作业。</p>\n</section><section class=\"lesson-section\" id=\"w1-section-2\"><h2>第1课 把一个问题写成数据</h2><h3>样本 特征 标签</h3>\n<p>假设要根据房间面积预测租金。一行历史记录是一份样本；预测时能获得的面积是特征；希望预测的租金是标签。真实任务还可能需要地区、房龄等特征，这里只用面积说明数据结构，并不假定面积足以解释所有差异。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>样本编号</th>\n<th>面积这个特征 x</th>\n<th>租金这个标签 y</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td>1</td>\n<td>3</td>\n</tr>\n<tr>\n<td>2</td>\n<td>2</td>\n<td>5</td>\n</tr>\n</tbody>\n</table></div>\n<p>本周计算使用上面两个抽象数值点，不把它们当作真实租房数据。预测连续数值叫<strong>回归</strong>；预测“垃圾邮件/正常邮件”这样的离散类别叫<strong>分类</strong>。两者都可以从带标签样本学习，属于监督学习。</p>\n<p>特征必须在实际做预测的时刻能够取得。若预测明天销量，却把明天最终成交金额作为输入，就可能提前泄露答案。能从文件中读到，不等于预测时能够使用。</p>\n<p>**停下来想：**预测学生下一次测验成绩，哪些可以作特征：过去成绩、本次测验结束后才统计的答对题数、此前练习时间？说明理由，不只回答“能”或“不能”。</p>\n<h3>标量 向量 矩阵与形状</h3>\n<p>标量是一个数，例如一个样本的面积。向量是一组按约定排列的数，例如同一样本的面积与房龄。矩阵可以用来组织多个样本：通常一行一个样本，一列一个特征。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>对象</th>\n<th>本周单特征写法</th>\n<th>一般形状</th>\n<th>含义</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>单个特征值</td>\n<td>1.0</td>\n<td>标量</td>\n<td>一个样本的一项信息</td>\n</tr>\n<tr>\n<td>一批单特征数据</td>\n<td><code>[1.0, 2.0]</code></td>\n<td><code>(n,)</code></td>\n<td>n个样本的一项特征</td>\n</tr>\n<tr>\n<td>特征矩阵 X</td>\n<td><code>[[1.0], [2.0]]</code></td>\n<td><code>(n,d)</code></td>\n<td>n个样本、d个特征</td>\n</tr>\n<tr>\n<td>权重向量 w</td>\n<td><code>[0.0]</code></td>\n<td><code>(d,)</code></td>\n<td>每个特征一个权重</td>\n</tr>\n<tr>\n<td>标签 y与预测值</td>\n<td><code>[3.0, 5.0]</code></td>\n<td><code>(n,)</code></td>\n<td>每个样本一个值</td>\n</tr>\n<tr>\n<td>偏置 b与损失 L</td>\n<td>0.0与17.0</td>\n<td>标量</td>\n<td>一个全局偏置与一个汇总误差</td>\n</tr>\n</tbody>\n</table></div>\n<p>多特征预测可以写成：</p>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：\\hat{\\mathbf{y}}=X\\mathbf{w}+b\"><img src=\"data:image/svg+xml;base64,\" width=\"145\" alt=\"\\hat{\\mathbf{y}}=X\\mathbf{w}+b\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<p>意思是每一行特征与权重作点积，再加上同一个偏置。若X是3行2列，权重有2个数，预测就应有3个数。不要只问代码是否能执行，还要问输出是否确实“一行样本对应一个预测”。NumPy中的 <code>(n,)</code> 与 <code>(n,1)</code> 不是同一种形状；混用时可能发生广播，意外产生 <code>(n,n)</code> 误差矩阵，详见<a href=\"../07_Python%E4%B8%8EC++%E7%BC%96%E7%A8%8B%E8%BE%85%E5%8A%A9.md\">编程辅助</a>。</p>\n<p>**本课练习：**自己造一个“3个样本、2个特征、1个标签”的数据表。标出X与y，给出形状，并说明列的顺序为什么不能在预测时随意交换。</p>\n</section><section class=\"lesson-section\" id=\"w1-section-3\"><h2>第2课 从模型到可以比较的损失</h2><h3>模型 参数与超参数</h3>\n<p>先选择最简单的一种预测规则：</p>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：\\hat y_i=wx_i+b\"><img src=\"data:image/svg+xml;base64,\" width=\"152\" alt=\"\\hat y_i=wx_i+b\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<p>其中i是样本编号，帽子表示预测值；w控制斜率，b控制整体上下平移。x是已经给定的输入，y是用于比较的标签，训练调整的是w和b。选择“用一条直线”是建模决定，并不是程序从所有可能规则中自动发现了直线。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>名称</th>\n<th>本周例子</th>\n<th>怎样确定</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>参数</td>\n<td>w、b</td>\n<td>通过训练数据与优化过程调整</td>\n</tr>\n<tr>\n<td>超参数</td>\n<td>学习率、更新次数</td>\n<td>由人设定或使用验证集选择</td>\n</tr>\n<tr>\n<td>数据</td>\n<td>x、y</td>\n<td>来源于观察或明确规定的生成过程</td>\n</tr>\n<tr>\n<td>模型形式</td>\n<td>一条直线</td>\n<td>由任务和建模假设选择</td>\n</tr>\n</tbody>\n</table></div>\n<p>先不训练，手工试三组参数：全零预测、恒定预测4、直线预测2x+1。训练的作用是用有组织的方式寻找参数，代替一直凭感觉猜数字。</p>\n<h3>为什么定义误差与均方误差</h3>\n<p>本周统一用“预测减真实值”定义残差：</p>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：e_i=\\hat y_i-y_i\"><img src=\"data:image/svg+xml;base64,\" width=\"135\" alt=\"e_i=\\hat y_i-y_i\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<p>残差为负表示预测偏低，为正表示偏高。若两个残差是2和−2，直接平均得到0，却不能说完全预测正确。均方误差先平方，再取平均：</p>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：L(w,b)=\\frac{1}{n}\\sum_{i=1}^{n}(wx_i+b-y_i)^2\"><img src=\"data:image/svg+xml;base64,\" width=\"362\" alt=\"L(w,b)=\\frac{1}{n}\\sum_{i=1}^{n}(wx_i+b-y_i)^2\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<p>这里n是样本数，求和符号表示把每个样本的平方残差加起来。本页采用普通MSE，<strong>没有额外除以2</strong>。平方避免正负抵消，同时更强调大误差；如果标签单位是元，MSE的单位是元的平方，不能把MSE直接当成平均相差多少元。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>预测规则</th>\n<th>两个预测</th>\n<th>两个残差</th>\n<th>MSE</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>w=0，b=0</td>\n<td>0，0</td>\n<td>−3，−5</td>\n<td>17</td>\n</tr>\n<tr>\n<td>w=0，b=4</td>\n<td>4，4</td>\n<td>1，−1</td>\n<td>1</td>\n</tr>\n<tr>\n<td>w=2，b=1</td>\n<td>3，5</td>\n<td>0，0</td>\n<td>0</td>\n</tr>\n</tbody>\n</table></div>\n<p>恒定预测训练标签的均值，是一种简单的<strong>基线</strong>。它回答“如果不利用输入特征，能做到什么程度”。在MSE下，最佳恒定预测是训练标签均值；这条结论依赖于使用平方损失。</p>\n<p>**本课练习：**改成w=1、b=0，独立写出预测、残差与MSE。再把一个标签5改成50，观察平方损失如何放大大误差。不要据此宣布MSE“不好”，而应讨论任务是否真的要让大错误付出更高代价。</p>\n</section><section class=\"lesson-section\" id=\"w1-section-4\"><h2>第3课 求导到底在求什么</h2><h3>从斜率到局部变化率</h3>\n<p>直线f(t)=3t+2每增加一小段t，输出增加约3倍，导数就是3。曲线的变化速度会随位置改变，例如：</p>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：f(t)=t^2,\\qquad f&#x27;(t)=2t\"><img src=\"data:image/svg+xml;base64,\" width=\"277\" alt=\"f(t)=t^2,\\qquad f&#x27;(t)=2t\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<p>在t=3处导数是6，表示t增加一个很小的量h时，函数值约增加6h。它不是说“t增加任意大小，输出都准确增加6倍”。例如h=0.1时，实际增加0.61，一阶估计是0.6。</p>\n<p>学习参数时，我们关心的是<strong>参数变化会怎样影响损失</strong>。对w求偏导，暂时固定b与所有样本；对b求偏导，暂时固定w与所有样本。把各参数的偏导收集起来，就得到梯度。本例梯度有两个分量，分别对应w与b。</p>\n<h3>本周真正需要的求导规则</h3>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>函数</th>\n<th>对t求导</th>\n<th>应怎样理解</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>常数c</td>\n<td>0</td>\n<td>输入变化不影响输出</td>\n</tr>\n<tr>\n<td>t</td>\n<td>1</td>\n<td>输入增加多少，输出增加多少</td>\n</tr>\n<tr>\n<td>t的平方</td>\n<td>2t</td>\n<td>同一曲线在不同位置有不同斜率</td>\n</tr>\n<tr>\n<td>c乘f(t)</td>\n<td>c乘f的导数</td>\n<td>整体缩放也缩放变化率</td>\n</tr>\n<tr>\n<td>f(t)+g(t)</td>\n<td>两个导数相加</td>\n<td>总变化来自各部分变化</td>\n</tr>\n<tr>\n<td>外层函数作用于内层函数</td>\n<td>外层导数乘内层导数</td>\n<td>一层变化经过另一层传播，称为链式法则</td>\n</tr>\n</tbody>\n</table></div>\n<p>对一个样本，把计算分成三步：预测z=wx+b，残差e=z−y，平方误差q=e²。q对e的导数是2e，e对z的导数是1，而z对w的导数是x。因此：</p>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：\\frac{\\partial e_i^2}{\\partial w}=2e_i\\,x_i\"><img src=\"data:image/svg+xml;base64,\" width=\"135\" alt=\"\\frac{\\partial e_i^2}{\\partial w}=2e_i\\,x_i\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<p>同理，z对b的导数是1，所以：</p>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：\\frac{\\partial e_i^2}{\\partial b}=2e_i\"><img src=\"data:image/svg+xml;base64,\" width=\"108\" alt=\"\\frac{\\partial e_i^2}{\\partial b}=2e_i\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<p>最后对所有样本求和并除以n，就得到真正需要写进程序的两个式子：</p>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：\\frac{\\partial L}{\\partial w}=\\frac{2}{n}\\sum_{i=1}^{n}e_i x_i\"><img src=\"data:image/svg+xml;base64,\" width=\"163\" alt=\"\\frac{\\partial L}{\\partial w}=\\frac{2}{n}\\sum_{i=1}^{n}e_i x_i\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：\\frac{\\partial L}{\\partial b}=\\frac{2}{n}\\sum_{i=1}^{n}e_i\"><img src=\"data:image/svg+xml;base64,\" width=\"138\" alt=\"\\frac{\\partial L}{\\partial b}=\\frac{2}{n}\\sum_{i=1}^{n}e_i\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<p>请留意：对w求导时多出来的x不是记忆口诀，它来自预测对w的变化率。若把残差定义改成“真实减预测”，整套推导的符号也必须一起调整，不能只改程序的一行残差。</p>\n<h3>用中心差分核对结果</h3>\n<p>如果已经有一个能计算损失的函数，就可以轻微改变w，观察两侧损失之差：</p>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：\\frac{\\partial L}{\\partial w}\\approx\\frac{L(w+h,b)-L(w-h,b)}{2h}\"><img src=\"data:image/svg+xml;base64,\" width=\"284\" alt=\"\\frac{\\partial L}{\\partial w}\\approx\\frac{L(w+h,b)-L(w-h,b)}{2h}\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<p>这个方法叫数值差分，返回的是近似导数值，不返回解析公式。h表示探测间距，<strong>不是训练学习率</strong>。本周可先用h=0.00001。h过大可能使局部近似变差，过小又可能使浮点数相减丢失有效数字，不能简单认为越小越准确。</p>\n<p>例如f(t)=t³在t=2处，解析导数是12；中心差分的精确表达式为12+h²，h=0.1时得到12.01。本周的线性回归MSE对参数是二次函数，精确算术下中心差分恰好能给出导数；实际程序仍有浮点误差。</p>\n<p>**本课练习：**固定w=0、b=0，先手算梯度，再用损失函数差分核对w的偏导。然后改为w=1、b=0重做，不能只验证原点。更多求导工具见<a href=\"../07_Python%E4%B8%8EC++%E7%BC%96%E7%A8%8B%E8%BE%85%E5%8A%A9.md\">编程辅助中的求导方式</a>。</p>\n</section><section class=\"lesson-section\" id=\"w1-section-5\"><h2>第4课 怎样走出一次学习更新</h2><h3>为什么沿负梯度更新</h3>\n<p>在当前位置，正偏导表示参数稍微增加会使损失增大，所以可以尝试减小参数；负偏导则相反。更新规则是：</p>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：w_{t+1}=w_t-\\alpha\\frac{\\partial L}{\\partial w}(w_t,b_t)\"><img src=\"data:image/svg+xml;base64,\" width=\"300\" alt=\"w_{t+1}=w_t-\\alpha\\frac{\\partial L}{\\partial w}(w_t,b_t)\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：b_{t+1}=b_t-\\alpha\\frac{\\partial L}{\\partial b}(w_t,b_t)\"><img src=\"data:image/svg+xml;base64,\" width=\"285\" alt=\"b_{t+1}=b_t-\\alpha\\frac{\\partial L}{\\partial b}(w_t,b_t)\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<p>t是更新轮次，alpha是学习率。两个偏导必须使用<strong>同一组旧参数</strong>计算，然后同时应用更新。不能先更新w，再把新w代入计算b的梯度，却仍把它称为同一次标准梯度下降。</p>\n<p>你在第二版笔记中提到的一阶泰勒近似，可以把这个方向解释得更清楚。记g为当前梯度、theta为参数向量；在变化足够小且函数可微的局部范围内：</p>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：L(\\theta-\\alpha g)\\approx L(\\theta)-\\alpha\\|g\\|^2\"><img src=\"data:image/svg+xml;base64,\" width=\"315\" alt=\"L(\\theta-\\alpha g)\\approx L(\\theta)-\\alpha\\|g\\|^2\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<p>其中梯度范数的平方就是各个偏导平方的和。当alpha为正、梯度不为零时，右侧比原损失小。但这是局部近似，步子过大时高阶项不能忽略，实际损失可以上升；对于更一般的模型，梯度为零也不自动表示找到全局最优。</p>\n<h3>两次更新全部算出来</h3>\n<p>在w=0、b=0处，残差是−3与−5：</p>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：g_w=(-3)\\times1+(-5)\\times2=-13\"><img src=\"data:image/svg+xml;base64,\" width=\"413\" alt=\"g_w=(-3)\\times1+(-5)\\times2=-13\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：g_b=(-3)+(-5)=-8\"><img src=\"data:image/svg+xml;base64,\" width=\"291\" alt=\"g_b=(-3)+(-5)=-8\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<p>学习率取0.1，第一次更新得到w=1.3、b=0.8。再次计算残差−0.9与−1.6，得到新梯度−4.1与−2.5；第二次更新得到w=1.71、b=1.05。</p>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>已完成更新次数</th>\n<th>w</th>\n<th>b</th>\n<th>对x=1的预测</th>\n<th>对x=2的预测</th>\n<th>当前MSE</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>17</td>\n</tr>\n<tr>\n<td>1</td>\n<td>1.3</td>\n<td>0.8</td>\n<td>2.1</td>\n<td>3.4</td>\n<td>1.685</td>\n</tr>\n<tr>\n<td>2</td>\n<td>1.71</td>\n<td>1.05</td>\n<td>2.76</td>\n<td>4.47</td>\n<td>0.16925</td>\n</tr>\n</tbody>\n</table></div>\n<p><img src=\"data:image/svg+xml;base64,\" alt=\"两次更新后的直线与训练样本\" /></p>\n<p>图中的横轴是输入x，纵轴是输出y。它展示参数如何改变预测线，不是独立测试的证据。两个点可以被无数其他形状的函数经过，仅拟合它们不能证明现实规律就是一条直线。</p>\n<p>把学习率改为1，从零出发一次就得到w=13、b=8，损失升到582.5。梯度方向可以没有算错，更新仍会因步长过大而失败。把损失整体除以2会让梯度也减半；在本例普通梯度下降、没有其他变化时，把学习率乘2才能保留相同的参数更新幅度。</p>\n<h3>一段可直接运行的最小Python程序</h3>\n<p>先读懂下面的完整程序。它只依赖Python自身，和数学推导一一对应：</p>\n<pre><code class=\"language-python\">samples = [(1.0, 3.0), (2.0, 5.0)]\nw, b = 0.0, 0.0\nalpha = 0.1\n\nfor step in range(3):\n    errors = [w * x + b - y for x, y in samples]\n    loss = sum(e * e for e in errors) / len(samples)\n    print(f&quot;step={step}, w={w:.6f}, b={b:.6f}, loss={loss:.6f}&quot;)\n    if step == 2:\n        break\n    dw = 2.0 * sum(e * x for e, (x, y) in zip(errors, samples)) / len(samples)\n    db = 2.0 * sum(errors) / len(samples)\n    w, b = w - alpha * dw, b - alpha * db\n</code></pre>\n<p>第一行把每个样本保存为一对数。列表推导式逐个计算残差；sum把各项加起来，len提供样本数；zip把残差与对应样本配对。最后一行的右侧先计算完毕，再把结果赋给w和b，所以使用的是同一组旧参数。</p>\n<p>预期输出中的loss依次为17.000000、1.685000、0.169250。分函数的完整版本和C++对应实现见<a href=\"../week01_support/reference_python.py\">Python参考</a>与<a href=\"../week01_support/reference_cpp.cpp\">C++参考</a>，运行步骤见<a href=\"../week01_support/README.md\">代码使用说明</a>。</p>\n</section><section class=\"lesson-section\" id=\"w1-section-6\"><h2>第5课 逐步减少编程帮助</h2><h3>先选一种语言完成</h3>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>阶段</th>\n<th>你做什么</th>\n<th>怎样判断完成</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>跟读</td>\n<td>运行参考版本，找到预测、损失、梯度和更新位置</td>\n<td>能指着代码说出每个输入与返回值的数学含义</td>\n</tr>\n<tr>\n<td>改动</td>\n<td>初始参数改为w=1、b=0，运行前先预测</td>\n<td>损失6.5，梯度−8与−5；能说明为何不同</td>\n</tr>\n<tr>\n<td>填空</td>\n<td>在starter里补预测、MSE与解析梯度</td>\n<td>两次更新、均值基线与中心差分检查一致</td>\n</tr>\n<tr>\n<td>迁移</td>\n<td>换成自己设计的3个样本，独立调用这些函数</td>\n<td>不依赖旧答案也能核对一轮更新</td>\n</tr>\n</tbody>\n</table></div>\n<p>填空文件：<a href=\"../week01_support/starter_python.py\">Python练习版</a>、<a href=\"../week01_support/starter_cpp.cpp\">C++练习版</a>。它们含待完成项，未填写前报错是预期行为。卡住时逐层看<a href=\"../week01_support/hints.txt\">提示</a>，不必立刻从空文件独立写完整实验框架。</p>\n<p>C++的平方写成 <code>e * e</code>，Python可写 <code>e * e</code> 或 <code>e ** 2</code>；两者的 <code>^</code> 都不是普通数值平方运算。C++里用 <code>2.0 / n</code> 避免整数除法。检查数组长度、样本对应关系和浮点数类型，往往比先调学习率更有效。</p>\n<h3>求导函数和库分别帮你做什么</h3>\n<div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>方式</th>\n<th>本周怎么用</th>\n<th>得到什么</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>解析求导后手写函数</td>\n<td>把上面的两个偏导实现为循环</td>\n<td>某组参数处的准确公式计算值，存在浮点舍入</td>\n</tr>\n<tr>\n<td>中心差分</td>\n<td>对损失函数左右取值</td>\n<td>近似导数数值，用来交叉检查</td>\n</tr>\n<tr>\n<td>SymPy符号求导</td>\n<td>用diff对数学表达式求导</td>\n<td>新的符号表达式，再代入数值得到结果</td>\n</tr>\n<tr>\n<td>PyTorch自动微分</td>\n<td>保留张量计算过程，再反向传播</td>\n<td>相对于参数的梯度数值</td>\n</tr>\n</tbody>\n</table></div>\n<p>NumPy负责数组运算，它的 <code>gradient</code> 是对采样数据作数值差分，并不自动追踪任意模型的计算图；SymPy的 <code>diff</code> 才是这里的符号求导。C++标准库没有通用符号或自动求导接口，本周用手写梯度与中心差分就能完成。<a href=\"https://numpy.org/doc/stable/reference/generated/numpy.gradient.html\">NumPy官方说明</a>、<a href=\"https://docs.sympy.org/latest/tutorials/intro-tutorial/calculus.html\">SymPy求导教程</a></p>\n<p><a href=\"../07_Python%E4%B8%8EC++%E7%BC%96%E7%A8%8B%E8%BE%85%E5%8A%A9.md\">Python与C++编程辅助</a>提供函数、容器、NumPy形状、SymPy与PyTorch的短示例以及C++库说明。现在先用这些工具核对一个导数；完整神经网络反向传播仍放在第9至10周。</p>\n</section><section class=\"lesson-section\" id=\"w1-section-7\"><h2>第6课 从训练成功走向有效评估</h2><h3>三份数据回答三个不同问题</h3>\n<p>训练集用于调整w和b；验证集用于选择学习率、更新轮数或其他方案；测试集用于方案固定后的最终评估。只要看过某份数据上的结果并据此改了方案，它就已经在帮助选择，不能继续假装它完全独立。</p>\n<p>第一次更新后的训练损失由17下降到1.685，但仍差于恒定预测4的基线损失1。第二次更新的0.16925虽优于基线，也仅说明训练样本上的比较。泛化关心的是未来相关样本；不仅要有独立评估，还要考虑评估数据是否代表将来的使用情形。</p>\n<p>训练损失和验证损失都高，可能是还没训练好、模型太简单、数据或实现有问题；训练很低而验证高，可能是过拟合、划分问题或分布变化。它们是排查线索，不是只看一张图就能确定的诊断。先检查实现和数据，再一次改变一个因素。</p>\n<h3>80个样本的带教实验</h3>\n<p>本周先运行已提供的参考实现，并回答它为何这样设计。数据生成规则是：</p>\n<div class=\"formula\"><button class=\"formula-zoom\" type=\"button\" title=\"放大公式\" aria-label=\"放大公式：y=2x+1+\\varepsilon,\\qquad\\varepsilon\\sim\\mathcal{N}(0,0.3^2)\"><img src=\"data:image/svg+xml;base64,\" width=\"429\" alt=\"y=2x+1+\\varepsilon,\\qquad\\varepsilon\\sim\\mathcal{N}(0,0.3^2)\" loading=\"lazy\"></button><span class=\"zoom-hint\" aria-hidden=\"true\">点击放大</span></div>\n<p>x在−2至2之间均匀采样。epsilon（ε）代表加在直线输出上的随机噪声；波浪号表示“服从某个分布”，N表示正态分布，括号里的0是均值，0.3²是方差，所以标准差是0.3。均值为0表示噪声总体不偏向正或负，不意味着这一批抽到的噪声均值恰好为0。这里先认识它如何让点偏离直线，概率分布的系统推导留到后续。</p>\n<p>使用随机种子42生成80个样本，打乱后固定48个训练、16个验证、16个测试。seed固定的是特定实现的随机过程；Python与C++使用相同seed不保证产生同一份数据，所以配套程序让C++读取Python导出的同一份CSV。</p>\n<p>三档学习率0.01、0.1、1.0都从零参数开始，在训练集最多更新100次。参考实现记录训练和验证轨迹，非有限数会被标记；只有完成并产生有限结果的候选参加选择。<strong>数值有限也不等于训练有效</strong>，损失巨大但有限的候选仍应如实保留。</p>\n<p>使用第100步的验证MSE选择方案，选择后只评估这一模型与训练均值基线在测试集上的MSE。不要用三个测试分数来选学习率。16个测试样本带来较大不确定性，这次实验用于学评估流程，不能证明某个学习率对所有数据最优。</p>\n<p>**本课练习：**在记录中指出“哪一行拟合参数、哪一步选择学习率、哪一步首次看测试结果”。再提出一个需要分组而不能随意按行划分的例子，例如同一用户多条记录。第2周再独立重写完整流程。</p>\n</section><section class=\"lesson-section\" id=\"w1-section-8\"><h2>综合自测 先答后看参考</h2><ol>\n<li>预测明天销量时，历史销量、天气预报、明天最终成交金额分别能否作特征？需要说明预测时点。</li>\n<li>3个样本、2个特征时，X、权重和预测的形状分别是什么？本周两个样本的损失又是什么形状？</li>\n<li>w、b、学习率和训练次数中，哪些是模型参数，哪些是超参数？</li>\n<li>两个残差为2与−2时，平均残差与MSE分别是多少？哪一个会隐藏预测错误？</li>\n<li>w=1、b=0时，本周两个点的损失、w偏导和b偏导分别是多少？请写中间过程。</li>\n<li>为什么w偏导中有x，而b偏导中没有？用链式法则解释。</li>\n<li>已经算出dw后立刻修改w，再用新w计算db，是否与文中的同步更新相同？</li>\n<li>损失整体除以2但学习率不变，一次梯度下降的参数变化会怎样？</li>\n<li>学习率改为1导致损失变大，是否必然说明梯度公式写错？</li>\n<li>把所有训练样本完整复制一遍，MSE与一次全量梯度更新是否改变？如果使用损失之和呢？</li>\n<li>SymPy diff、NumPy gradient与PyTorch backward返回或计算的对象有什么区别？本周不使用任何第三方求导库能否训练？</li>\n<li>看完测试误差后决定再换学习率，之后得到的同一测试集分数还可以当作首次独立评估吗？</li>\n</ol>\n</section><section class=\"lesson-section\" id=\"w1-section-9\"><h2>自测参考与过关方式</h2><details class=\"answer\"><summary>已作答，展开参考与过关方式</summary><ol>\n<li>历史销量通常可用；天气预报需使用预测时已经发布的版本；明天最终成交金额当时未知，不应作为输入。还需检查特征是否隐含标签。</li>\n<li>X为(3,2)，权重为(2,)，预测为(3,)；MSE把所有样本误差汇总成一个标量。标签与预测应逐样本一一对应。</li>\n<li>w、b是参数；学习率、训练次数是超参数。参数可以通过学习确定，但决定怎样训练也需要独立验证。</li>\n<li>平均残差0，MSE为4；直接平均残差会因为符号抵消而隐藏错误。</li>\n<li>预测1、2，残差−2、−3，损失(4+9)/2=6.5；w偏导−2×1−3×2=−8，b偏导−2−3=−5。</li>\n<li>预测wx+b对w的导数为x，对b的导数为1；外层平方误差的2e通过链式法则与它们相乘。</li>\n<li>不同。它使用了两个不同位置的梯度分量；应在旧w、b处算好两个偏导再更新。</li>\n<li>梯度与参数变化都减半；对本例普通梯度下降，把学习率乘2才恢复原更新幅度。</li>\n<li>不必然。正确的局部下降方向配上过大步长也会增加损失；本例从零更新得到w=13、b=8，MSE=582.5。</li>\n<li>对同一参数的一次全量更新，MSE及其梯度不变；损失之和及其梯度翻倍。按样本逐步更新时，执行次数也可能改变，要另行讨论。</li>\n<li>SymPy生成符号导数表达式，NumPy gradient估计采样值的数值导数，PyTorch backward通过计算图把梯度累积到相应张量。解析手写梯度足以完成本周训练。</li>\n<li>不可以。该测试结果已参与方案选择。可以把它转为开发证据，最终评价需要新的独立数据或明确声明评估已受选择影响。</li>\n</ol>\n<p>用<a href=\"../02_%E8%AE%B2%E8%A7%A3%E7%90%86%E8%A7%A3%E5%AE%9E%E8%B7%B5%E9%AA%8C%E6%94%B6.md\">三条验收线</a>分别评分：讲解、理解、实践各至少6/8且无0分。主讲解用8–10分钟回答“数据到参数更新再到评估怎样连起来”；实践只要求一种语言的三个核心函数与一次变式正确。运行参考程序是起点，独立补完和解释才是过关证据。</p>\n</details></section><section class=\"lesson-section\" id=\"w1-section-10\"><h2>本周已讲授与后续内容的边界</h2><div class=\"table-scroll\"><table>\n<thead>\n<tr>\n<th>规划目标</th>\n<th>对应讲解</th>\n<th>验收证据</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>数据概念与预测任务</td>\n<td>第1课的数据表与预测时点</td>\n<td>自测1，自己造一个任务</td>\n</tr>\n<tr>\n<td>向量与矩阵形状</td>\n<td>第1课形状表与3×2练习</td>\n<td>自测2，解释一个广播错误</td>\n</tr>\n<tr>\n<td>模型与参数</td>\n<td>第2课三种预测规则</td>\n<td>自测3，说明参数与超参数</td>\n</tr>\n<tr>\n<td>损失和基线</td>\n<td>第2课逐样本计算，第6课比较</td>\n<td>自测4，完整误差表</td>\n</tr>\n<tr>\n<td>求导和首次更新</td>\n<td>第3、4课推导与程序</td>\n<td>自测5至10，梯度核对</td>\n</tr>\n<tr>\n<td>编程能力</td>\n<td>第5课和辅助文档</td>\n<td>一种语言的填空版与变式</td>\n</tr>\n<tr>\n<td>训练与泛化</td>\n<td>第6课的评估流程</td>\n<td>自测12，解释一次结果的范围</td>\n</tr>\n</tbody>\n</table></div>\n<p>第2周进一步学习批量矩阵实现、线性回归的完整优化实验和独立编程；概率分类与交叉熵从第3周开始。2026年10月23日已补充<a href=\"../%E9%98%85%E8%AF%BB%E7%89%88/index.html#week-2\">第2–24周交互课程</a>，包括教学正文、分步代码、练习、自测与参考答案。项目中的真实训练与评估仍需自己完成并留下记录。</p>\n</section>","toc":[{"id":"w1-section-1","title":"学习安排与内容对照"},{"id":"w1-section-2","title":"第1课 把一个问题写成数据"},{"id":"w1-section-3","title":"第2课 从模型到可以比较的损失"},{"id":"w1-section-4","title":"第3课 求导到底在求什么"},{"id":"w1-section-5","title":"第4课 怎样走出一次学习更新"},{"id":"w1-section-6","title":"第5课 逐步减少编程帮助"},{"id":"w1-section-7","title":"第6课 从训练成功走向有效评估"},{"id":"w1-section-8","title":"综合自测 先答后看参考"},{"id":"w1-section-9","title":"自测参考与过关方式"},{"id":"w1-section-10","title":"本周已讲授与后续内容的边界"}]};
